// tongTien = "total amount", gio = "cart", apGiamGia = "apply discount", phiGiao = "delivery fee",
// kiemTraDon = "check order", datHang = "place order", sauGiam = "after discount", dat = "passed"
const MENU = { "ca-phe-den": 25000, "ca-phe-sua": 29000, "tra-dao": 34500, "banh-mi": 20000 };

function tongTien(gio) {
  let tong = 0;
  for (const dong of gio) tong += MENU[dong.mon] * dong.soLuong;
  return tong;
}

function apGiamGia(tong, ma) {
  if (ma === "GIAM10" && tong >= 100000) return tong - tong / 10;
  return tong;
}

function phiGiao(tong) {
  if (tong < 0) return "invalid total";
  if (tong >= 500000) return 0;
  return 30000;
}

function kiemTraDon(don) {
  if (don.ten.trim() === "") return "missing name";
  if (!/^0\d{9}$/.test(don.sdt)) return "invalid phone number";
  if (don.gio < 7 || don.gio > 21) return "outside order hours";
  return "ok";
}

function datHang(don, gio, ma) {
  const kq = kiemTraDon(don);
  if (kq !== "ok") return "rejected: " + kq;
  if (gio.length === 0) return "rejected: empty cart";
  const tong = tongTien(gio);
  const sauGiam = apGiamGia(tong, ma);
  const phi = phiGiao(tong);
  return sauGiam + phi;
}

const ai = { ten: "An", sdt: "0901234567", gio: 9 };
const donLon = [{ mon: "ca-phe-den", soLuong: 20 }, { mon: "banh-mi", soLuong: 1 }];
const bang = [
  ["normal order", datHang(ai, [{ mon: "ca-phe-sua", soLuong: 1 }], ""), 59000],
  ["large order, no code", datHang(ai, donLon, ""), 520000],
  ["large order, with code GIAM10", datHang(ai, donLon, "GIAM10"), 498000],
  ["wrong phone number", datHang({ ten: "An", sdt: "12345", gio: 9 }, donLon, ""), "rejected: invalid phone number"],
  ["empty cart", datHang(ai, [], ""), "rejected: empty cart"],
];
let dat = 0;
for (const [ten, that, mong] of bang) {
  if (that === mong) dat++;
  else console.log("✗ " + ten + ": got " + that + ", expected " + mong);
}
console.log("Passed " + dat + "/" + bang.length);
console.log("Ready to hand over to the customer: " + (dat === bang.length ? "yes" : "not yet"));

